def solve(n):
    if n <= 2:
        return 0
    # count prime 2 if n>2
    count = 1
    size = (n - 2) // 2  # number of odd candidates >=3 and < n
    if size <= 0:
        return count
    is_prime = bytearray(b'\x01') * size  # is_prime[i] -> number 2*i+3
    import math
    limit = int(math.isqrt(n - 1))
    max_i = (limit - 3) // 2
    for i in range(max_i + 1):
        if is_prime[i]:
            p = 2 * i + 3
            start = (p * p - 3) // 2
            step = p
            # mark composites
            is_prime[start::step] = b'\x00' * ((size - start - 1) // step + 1)
    return count + sum(is_prime)

