def solve(meetings):
    """Return the maximum number of non‑overlapping meetings that can be attended.
    Each meeting is a sequence with at least two numeric values: start and end.
    Meetings where start > end are considered invalid and ignored.
    A meeting may start exactly when the previous one ends (start >= previous end).
    """
    # Filter out invalid entries
    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        # Ensure numeric and start <= end
        if not isinstance(start, (int, float)) or not isinstance(end, (int, float)):
            continue
        if start > end:
            continue
        valid.append((start, end))
    if not valid:
        return 0
    # Greedy by earliest finishing time
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for start, end in valid:
        if start >= current_end:
            count += 1
            current_end = end
    return count

