def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search (O(n log n)).
    """
    import bisect
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

def solve(lst):
    """Flatten a nested list of integers without recursion.
    The function walks the structure using an explicit stack to avoid recursion limits.
    """
    result = []
    stack = [lst]
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            # Push children in reverse order so they are processed in original order
            for sub in reversed(item):
                stack.append(sub)
        else:
            result.append(item)
    result.reverse()
    return result

