def solve(meetings):
    """Return the maximum number of non‑overlapping meetings that can be attended.
    Each meeting is given as an iterable with at least two values (start, end).
    If a meeting's start is greater than its end, the two values are swapped so the
    interval is interpreted correctly. Meetings may touch (i.e., a meeting can start
    exactly when the previous one ends).
    """
    # Normalize meetings to (start, end) with start <= end
    normalized = []
    for m in meetings:
        try:
            s, e = m[0], m[1]
        except Exception:
            # ignore malformed entries
            continue
        # If not numbers, attempt to convert; if fails, skip
        if not isinstance(s, (int, float)):
            try:
                s = int(s)
            except Exception:
                continue
        if not isinstance(e, (int, float)):
            try:
                e = int(e)
            except Exception:
                continue
        if s > e:
            s, e = e, s
        normalized.append((s, e))
    if not normalized:
        return 0
    # Greedy: sort by earliest end time, then by start time
    normalized.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in normalized:
        if s >= current_end:
            count += 1
            current_end = e
    return count

