def solve(n, edges):
    import heapq
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a,b,w in edges:
        adj[a].append((b,w))
        adj[b].append((a,w))
    # Dijkstra from 0 to n-1
    INF = 10**18
    dist = [INF]*n
    if n==0:
        return -1
    dist[0]=0
    heap = [(0,0)]
    while heap:
        d,u = heapq.heappop(heap)
        if d!=dist[u]:
            continue
        if u==n-1:
            break
        for v,w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v]=nd
                heapq.heappush(heap,(nd,v))
    if n==1:
        return 0
    return dist[n-1] if dist[n-1]!=INF else -1

