def solve(weights, values, capacity):
    """Zero‑one knapsack using a dictionary to handle large capacities efficiently.
    Returns the maximum total value achievable without exceeding *capacity*.
    """
    if capacity <= 0 or not weights:
        return 0
    # states: mapping total_weight -> best value for that weight
    states = {0: 0}
    for w, v in zip(weights, values):
        # iterate over a snapshot of current states to avoid using the same item multiple times
        new_states = {}
        for cur_w, cur_val in states.items():
            nxt_w = cur_w + w
            if nxt_w > capacity:
                continue
            nxt_val = cur_val + v
            # if this weight not seen or we have a better value, record it
            if nxt_val > states.get(nxt_w, -1):
                new_states[nxt_w] = nxt_val
        # merge new states, keeping the best value for each weight
        for k, v_new in new_states.items():
            if v_new > states.get(k, -1):
                states[k] = v_new
    return max(states.values())

def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting (tails array) with binary search.
    Handles empty input and works for any comparable elements.
    """
    import bisect
    tails = []
    for x in nums:
        # Find insertion point in tails (first >= x)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

