def solve(matrix):
    """Return the determinant of a square integer matrix.
    Empty matrix has determinant 1.
    Uses exact rational arithmetic (fractions.Fraction) with Gaussian elimination.
    """
    from fractions import Fraction
    # empty matrix case
    if not matrix:
        return 1
    n = len(matrix)
    # ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # copy as Fractions
    a = [[Fraction(int(val)) for val in row] for row in matrix]
    sign = 1
    for i in range(n):
        # find pivot row
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            sign = -sign
        pivot_val = a[i][i]
        # eliminate rows below
        for j in range(i + 1, n):
            if a[j][i] == 0:
                continue
            factor = a[j][i] / pivot_val
            for k in range(i, n):
                a[j][k] -= factor * a[i][k]
    # product of diagonal entries
    det = Fraction(sign, 1)
    for i in range(n):
        det *= a[i][i]
    # det should be integer
    return int(det)

