def solve(n, edges):
    """Return the lexicographically smallest topological ordering of nodes 0..n-1.
    edges is a list of [a, b] meaning a must come before b. If a cycle exists, return [] .
    Uses Kahn's algorithm with a min-heap to always pick the smallest available node.
    """
    from heapq import heappush, heappop
    # build adjacency list and indegree count
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        # Validate indices
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        node = heappop(heap)
        order.append(node)
        for nb in adj[node]:
            indeg[nb] -= 1
            if indeg[nb] == 0:
                heappush(heap, nb)
    if len(order) != n:
        return []  # cycle detected
    return order

